-- 051 — agenda da comunidade. Entre uma edição e outra a comunidade marca
-- meetup, live, workshop ou demo day. Dono e organizador criam; publicar
-- avisa quem é membro e quem segue (lib/follows.ts communityAudience). RSVP
-- "vou"/"talvez" com lotação, .ics, live embutida (só YouTube e Twitch) e,
-- no demo day, o pedido de palco com um projeto da pessoa.
--
-- Datas em TEXT "YYYY-MM-DD HH:MM:SS" UTC, como o resto do schema. O
-- formulário manda horário de Brasília e lib/meetups.ts converte.

CREATE TABLE meetups (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "communityId" INTEGER NOT NULL REFERENCES communities("id") ON DELETE CASCADE,
  "kind" TEXT NOT NULL CHECK ("kind" IN ('meetup', 'live', 'workshop', 'demo_day')),
  "title" TEXT NOT NULL CHECK (char_length("title") BETWEEN 3 AND 100),
  "description" TEXT CHECK ("description" IS NULL OR char_length("description") <= 3000),
  "startsAt" TEXT NOT NULL,
  "endsAt" TEXT,
  "location" TEXT,
  -- link da sala (Meet, Zoom, Jitsi…): só aparece pra quem respondeu
  "onlineUrl" TEXT,
  -- live: URL canônica do YouTube (youtube.com/embed/ID) ou da Twitch
  -- (player.twitch.tv/?channel=X ou ?video=vID); o parent do iframe da
  -- Twitch entra na hora de mostrar, pelo domínio da página
  "embedUrl" TEXT,
  "capacity" INTEGER CHECK ("capacity" IS NULL OR "capacity" >= 1),
  -- quem criou: ator (fica apontando pra linha anonimizada na exclusão)
  "createdBy" INTEGER REFERENCES members("id"),
  -- NULL = rascunho, só dono e organizador veem
  "publishedAt" TEXT,
  "cancelledAt" TEXT,
  -- SEQUENCE do .ics: sobe quando o horário muda, pro app de agenda atualizar
  "sequence" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "updatedAt" TEXT
);
CREATE INDEX idx_meetups_community_starts ON meetups ("communityId", "startsAt");
CREATE INDEX idx_meetups_published ON meetups ("communityId", "publishedAt");

CREATE TABLE meetup_rsvps (
  "meetupId" INTEGER NOT NULL REFERENCES meetups("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "status" TEXT NOT NULL CHECK ("status" IN ('vou', 'talvez')),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  PRIMARY KEY ("meetupId", "memberId")
);
CREATE INDEX idx_meetup_rsvps_member ON meetup_rsvps ("memberId");

-- quem conduz (aparece na página). Sem ninguém marcado, quem criou conduz.
CREATE TABLE meetup_hosts (
  "meetupId" INTEGER NOT NULL REFERENCES meetups("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  PRIMARY KEY ("meetupId", "memberId")
);
CREATE INDEX idx_meetup_hosts_member ON meetup_hosts ("memberId");

-- demo day: membro pede palco com um projeto dele; o organizador aceita ou
-- recusa e os aceitos viram a programação. Um pedido por projeto por evento.
CREATE TABLE meetup_stage_requests (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "meetupId" INTEGER NOT NULL REFERENCES meetups("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "teamId" INTEGER NOT NULL REFERENCES teams("id") ON DELETE CASCADE,
  "pitch" TEXT NOT NULL CHECK (char_length("pitch") BETWEEN 1 AND 280),
  "status" TEXT NOT NULL DEFAULT 'pedido' CHECK ("status" IN ('pedido', 'aceito', 'recusado')),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "decidedAt" TEXT,
  UNIQUE ("meetupId", "teamId")
);
CREATE INDEX idx_meetup_stage_member ON meetup_stage_requests ("memberId");
